<div class="news-admin-header"><div><p class="eyebrow">Qualification structure</p><h1>Programme Levels</h1><p class="admin-lead">Maintain NVQ and qualification level descriptions, ordering and publication.</p></div><a class="button" href="<?= e(url('admin/programme-levels/create')) ?>"><i class="bi bi-plus-lg"></i> Add level</a></div>
<form class="panel news-filters" method="get"><label class="news-filter-search">Search <input type="search" name="q" value="<?= e($q) ?>" placeholder="Name, code, qualification or description"></label><label>Status <select name="status"><option value="">All statuses</option><?php foreach (['published', 'draft', 'archived'] as $item): ?><option value="<?= $item ?>" <?= $status === $item ? 'selected' : '' ?>><?= ucfirst($item) ?></option><?php endforeach; ?></select></label><button class="button" type="submit">Filter</button><a class="button button-secondary" href="<?= e(url('admin/programme-levels')) ?>">Reset</a></form>
<section class="panel"><div class="panel-heading"><h2>Level directory</h2><span class="panel-note"><?= (int) $pager['total'] ?> levels · clear filters to reorder</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Level</th><th>Qualification</th><th>Programmes</th><th>Status</th><th></th></tr></thead><tbody id="levelsList"><?php foreach ($rows as $row): ?><tr data-id="<?= (int) $row['id'] ?>"><td><span class="drag-handle"><i class="bi bi-grip-vertical"></i></span><strong><?= e($row['code']) ?> · <?= e($row['name']) ?></strong><small><?= e($row['slug']) ?></small></td><td><?= e($row['qualification']) ?></td><td><?= (int) $row['programme_count'] ?></td><td><span class="news-status status-<?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td class="actions"><a href="<?= e(url('admin/programme-levels/' . $row['id'] . '/edit')) ?>">Edit</a><?php if ($row['status'] === 'published'): ?><a href="<?= e(url('programme-levels/' . ($row['seo_slug'] ?: $row['slug']))) ?>" target="_blank" rel="noopener">View</a><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5">No programme levels match the selected filters.</td></tr><?php endif; ?></tbody></table></div></section>
<?= render_pagination($pager, '/admin/programme-levels', array_filter(['q' => $q, 'status' => $status])) ?>
<script src="https://cdn.jsdelivr.net/npm/sortablejs@1.15.6/Sortable.min.js"></script><script>
document.addEventListener('DOMContentLoaded', () => { const list = document.getElementById('levelsList'); if (!list || <?= json_encode($q !== '' || $status !== '' || (int) $pager['pages'] !== 1) ?>) return; new Sortable(list, {animation: 150, handle: '.drag-handle', onEnd: async () => { const response = await fetch(<?= json_encode(url('admin/programme-levels/reorder')) ?>, {method: 'POST', headers: {'Content-Type': 'application/json', 'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]')?.content || '', 'Accept': 'application/json'}, body: JSON.stringify({levels: [...list.children].map((row) => Number(row.dataset.id))})}); const result = await response.json(); if (!response.ok || !result.ok) window.alert(result.message || 'Could not save order.'); }}); });
</script>
